    public int[][] matrixReshape(int[][] mat, int r, int c) {
        int m = mat.length, n = mat[0].length;
        if (m * n != r * c) return mat;
        List<Integer> list = new ArrayList<>();
        for (int[] row : mat) for (int x : row) list.add(x);
        int[][] res = new int[r][c];
        int idx = 0;
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                res[i][j] = list.get(idx++);
            }
        }
        return res;
    }
}

