                mat[top][i] = val
                val += 1
            top += 1
            for i in range(top, bottom + 1):
                mat[i][right] = val
                val += 1
            right -= 1
            for i in range(right, left - 1, -1):
                mat[bottom][i] = val
                val += 1
            bottom -= 1
            for i in range(bottom, top - 1, -1):
                mat[i][left] = val
                val += 1
            left += 1
        return mat

