                for (int d = 0; d < 8; d++) {
                    int nr = r + dr[d], nc = c + dc[d];
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n && copy[nr][nc] == 1) live++;
                }
                if (copy[r][c] == 1 && (live < 2 || live > 3)) board[r][c] = 0;
                if (copy[r][c] == 0 && live == 3) board[r][c] = 1;
            }
        }
    }
