class Solution {
    public void gameOfLife(int[][] board) {
        int m = board.length, n = board[0].length;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                int live = countLive(board, r, c, m, n);
                if ((board[r][c] & 1) == 1 && (live == 2 || live == 3)) {
                    board[r][c] |= 2;
                } else if ((board[r][c] & 1) == 0 && live == 3) {
                    board[r][c] |= 2;
                }
            }
        }
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                board[r][c] >>= 1;
            }
        }
    }
    private int countLive(int[][] b, int r, int c, int m, int n) {
        int cnt = 0;
        for (int i = Math.max(0, r - 1); i <= Math.min(m - 1, r + 1); i++) {
            for (int j = Math.max(0, c - 1); j <= Math.min(n - 1, c + 1); j++) {
                if (i == r && j == c) continue;
                cnt += b[i][j] & 1;
            }
        }
        return cnt;
    }
}

