            for c in range(n):
                live = 0
                for i in range(max(0, r - 1), min(m, r + 2)):
                    for j in range(max(0, c - 1), min(n, c + 2)):
                        if i == r and j == c:
                            continue
                        live += board[i][j] & 1
                if (board[r][c] & 1) == 1 and live in (2, 3):
                    board[r][c] |= 2
                elif (board[r][c] & 1) == 0 and live == 3:
                    board[r][c] |= 2
        for r in range(m):
            for c in range(n):
                board[r][c] >>= 1

